item.content:encoded:
.tech-hover img {
    transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1),
                filter 0.4s ease;
}

.tech-hover img:hover {
    transform: scale(1.08) translateY(-6px) rotate(0.7deg);
    filter: brightness(1.15);
}

/* Rotating gear logo */
.gear-rotate img {
    display: block;
    margin: 0 auto;
    transform-origin: center center;
    animation: gearspin 7s linear infinite;
}

@keyframes gearspin {
    from {
        transform: rotate(0deg);
    }
    to {
        transform: rotate(360deg);
    }
}

/* Power BI embed card */
.pbi-card {
    max-width: 1200px;
    margin: 2.5rem auto;
    padding: 1.75rem 1.75rem 2rem;
    background: #ffffff;
    border-radius: 18px;
    border: 1px solid #e5e7eb;          /* light grey border */
    box-shadow: 0 18px 45px rgba(15,23,42,.12);
}

/* Header row above the report */
.pbi-card-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 1rem;
}

.pbi-card-title {
    font-size: 1.4rem;
    font-weight: 700;
    letter-spacing: .01em;
}

.pbi-card-subtitle {
    font-size: .9rem;
    color: #6b7280;
}

/* “chip” style tag on the right */
.pbi-chip {
    font-size: .75rem;
    padding: .2rem .6rem;
    border-radius: 999px;
    background: #e0f2fe;
    color: #0369a1;
    font-weight: 600;
}

/* Responsive 16:9 wrapper */
.pbi-frame-wrapper {
    position: relative;
    width: 100%;
    padding-bottom: 56.25%; /* 16:9 */
    overflow: hidden;
    border-radius: 12px;
}

/* Make iframe fill wrapper */
.pbi-frame-wrapper iframe {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    border: 0;
}

/* Base link style */
.nav-shine a {
    color: #0a1a2f;                       /* your dark navy */
    padding: 6px 14px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.15); 
    background-color: rgba(255, 255, 255, 0.05);

    transition:
        color 0.25s ease,
        background-color 0.25s ease,
        border-color 0.25s ease,
        transform 0.22s cubic-bezier(0.22, 1, 0.36, 1);
}

/* Hover effect */
.nav-shine a:hover {
    color: #ffffff;                        /* bright text */
    background-color: rgba(255, 255, 255, 0.18); /* modern soft glow */
    border-color: rgba(255, 255, 255, 0.35);     /* slightly stronger border */
    transform: translateY(-2px);           /* minimal lift */
}
